76|/**
77| * Register a provider for a capability.
78| */
79|export function registerProvider<T>(capabilityId: string, provider: Provider<T>): void {
80|	const capability = capabilities.get(capabilityId);
81|	if (!capability) {
82|		throw new Error(`Unknown capability: "${capabilityId}". Define it first with defineCapability().`);
83|	}
84|
85|	// Store provider metadata (for cross-capability display)
86|	if (!providerMeta.has(provider.id)) {
87|		providerMeta.set(provider.id, {
88|			displayName: provider.displayName,
89|			description: provider.description,
90|		});
91|	}
92|
93|	// Track which capabilities this provider is registered for
94|	if (!providerCapabilities.has(provider.id)) {
95|		providerCapabilities.set(provider.id, new Set());
96|	}
97|	providerCapabilities.get(provider.id)!.add(capabilityId);
98|
99|	// Insert in priority order (highest first)
100|	const providers = capability.providers as Provider<T>[];
101|	const idx = providers.findIndex(p => p.priority < provider.priority);
102|	if (idx === -1) {
103|		providers.push(provider);
104|	} else {
105|		providers.splice(idx, 0, provider);
106|	}
107|}
108|
109|// =============================================================================
110|// Loading API
111|// =============================================================================
112|
113|/**
114| * Async loading logic shared by loadCapability().
115| */
116|async function loadImpl<T>(
117|	capability: Capability<T>,
118|	providers: Provider<T>[],
119|	ctx: LoadContext,
120|	options: LoadOptions<T>,
121|): Promise<CapabilityResult<T>> {
122|	const allItems: Array<T & { _source: SourceMeta; _shadowed?: boolean }> = [];
123|	const suppressedItems = new Set<T & { _source: SourceMeta; _shadowed?: boolean }>();
124|	const disabledItems = new Set<T & { _source: SourceMeta; _shadowed?: boolean }>();
125|	const allWarnings: string[] = [];
126|	const contributingProviders: string[] = [];
127|	const disabledExtensionIds = new Set<string>(
128|		options.disabledExtensions ?? settings?.get("disabledExtensions") ?? [],
129|	);
130|
131|	const results = await Promise.all(
132|		providers.map(async provider => {
133|			try {
134|				const result = await logger.time(
135|					`capability:${capability.id}:${provider.id}`,
136|					provider.load.bind(provider),
137|					ctx,
138|				);
139|				return { provider, result };
140|			} catch (error) {
141|				logger.debug(`capability:${capability.id}:${provider.id}:error`);
142|				return { provider, error };
143|			}
144|		}),
145|	);
146|
147|	for (const entry of results) {
148|		const { provider } = entry;
149|		if ("error" in entry) {
150|			allWarnings.push(`[${provider.displayName}] Failed to load: ${entry.error}`);
151|			continue;
152|		}
153|
154|		const result = entry.result;
155|		if (!result) continue;
156|
157|		if (result.warnings) {
158|			allWarnings.push(...result.warnings.map(w => `[${provider.displayName}] ${w}`));
159|		}
160|
161|		let contributedItemCount = 0;
162|		for (const item of result.items) {
163|			const itemWithSource = item as T & { _source: SourceMeta };
164|			if (!itemWithSource._source) {
165|				allWarnings.push(`[${provider.displayName}] Item missing _source metadata, skipping`);
166|				continue;
167|			}
168|
169|			const extensionId = capability.toExtensionId?.(itemWithSource);
170|			const isDisabled = extensionId !== undefined && disabledExtensionIds.has(extensionId);
171|			if (isDisabled && !options.includeDisabled) {
172|				continue;
173|			}
174|
175|			if (options.filter && !options.filter(itemWithSource)) {
176|				continue;
177|			}
178|
179|			if (isDisabled) {
180|				disabledItems.add(itemWithSource);
181|			}
182|
183|			if (options.suppress?.(itemWithSource)) {
184|				// Suppressed items still claim their dedupe key below, so a
185|				// suppressed higher-priority item shadows same-key lower-priority
186|				// ones, but they never survive or equivalence-shadow survivors.
187|				itemWithSource._source.providerName = provider.displayName;
188|				const suppressed = itemWithSource as T & { _source: SourceMeta; _shadowed?: boolean };
189|				suppressedItems.add(suppressed);
190|				allItems.push(suppressed);
191|				continue;
192|			}
193|
194|			itemWithSource._source.providerName = provider.displayName;
195|			allItems.push(itemWithSource as T & { _source: SourceMeta; _shadowed?: boolean });
196|			contributedItemCount += 1;
197|		}
198|
199|		if (contributedItemCount > 0) {
200|			contributingProviders.push(provider.id);
201|		}
202|	}
203|
204|	// Deduplicate by key or semantic equivalence (first wins = highest priority)
205|	const seen = new Set<string>();
206|	const deduped: Array<T & { _source: SourceMeta }> = [];
207|	const equivalent = capability.equivalent;
208|
209|	for (const item of allItems) {
210|		const key = capability.key(item);
211|
212|		if (disabledItems.has(item)) {
213|			// Disabled rows never claim their key or equivalence class, so they
214|			// can't shadow an enabled survivor (issue #11870). But when an
215|			// earlier enabled item already owns the key or an equivalent
216|			// identity, the disabled row is a lower-priority loser: mark it
217|			// shadowed so the dashboard treats it as a shadowed no-op instead of
218|			// an independently toggleable row.
219|			const keySeen = key !== undefined && seen.has(key);
220|			const aliasSeen =
221|				!keySeen &&
222|				equivalent !== undefined &&
223|				deduped.some(existing => !disabledItems.has(existing) && equivalent(existing, item));
224|			if (keySeen || aliasSeen) item._shadowed = true;
225|			if (!suppressedItems.has(item)) deduped.push(item);
226|			continue;
227|		}
228|
229|		if (suppressedItems.has(item)) {
230|			// Claim key ownership (same-name precedence, including disabled
231|			// state) without surviving or equivalence-shadowing survivors.
232|			if (key !== undefined) seen.add(key);
233|			continue;
234|		}
235|
236|		if (key === undefined) {
237|			deduped.push(item);
238|			continue;
239|		}
240|
241|		const keySeen = seen.has(key);
242|		seen.add(key);
243|		const aliasSeen =
244|			!keySeen &&
245|			equivalent !== undefined &&
246|			deduped.some(existing => !disabledItems.has(existing) && equivalent(existing, item));
247|		if (keySeen || aliasSeen) {
248|			item._shadowed = true;
249|		} else {
250|			deduped.push(item);
251|		}
252|	}
253|
254|	// Validate items (only non-shadowed items)
255|	if (capability.validate && !options.includeInvalid) {
256|		for (let i = deduped.length - 1; i >= 0; i--) {
257|			const error = capability.validate(deduped[i]);
258|			if (error) {
259|				const source = deduped[i]._source;
260|				allWarnings.push(
261|					`[${source?.providerName ?? "unknown"}] Invalid item at ${source?.path ?? "unknown"}: ${error}`,
262|				);
263|				deduped.splice(i, 1);
264|			}
265|		}
266|	}
267|
268|	return {
269|		items: deduped,
270|		all: suppressedItems.size > 0 ? allItems.filter(item => !suppressedItems.has(item)) : allItems,
271|		warnings: allWarnings,
272|		providers: contributingProviders,
273|	};
274|}
275|
276|/**
277| * Filter providers based on options and disabled state.
278| */
279|function filterProviders<T>(capability: Capability<T>, options: LoadOptions<T>): Provider<T>[] {
280|	let providers = (capability.providers as Provider<T>[]).filter(p => !disabledProviders.has(p.id));
281|
282|	if (options.providers) {
283|		const allowed = new Set(options.providers);
284|		providers = providers.filter(p => allowed.has(p.id));
285|	}
286|	if (options.excludeProviders) {
287|		const excluded = new Set(options.excludeProviders);
288|		providers = providers.filter(p => !excluded.has(p.id));
289|	}
290|
291|	return providers;
292|}
293|
294|/**
295| * Load a capability by ID.
296| */
297|export async function loadCapability<T>(
298|	capabilityId: string,
299|	options: LoadOptions<T> = {},
300|): Promise<CapabilityResult<T>> {
301|	const capability = capabilities.get(capabilityId) as Capability<T> | undefined;
302|	if (!capability) {
303|		throw new Error(`Unknown capability: "${capabilityId}"`);
304|	}
305|
306|	const cwd = options.cwd ?? getProjectDir();
307|	const home = os.homedir();
308|	const repoRoot = await findRepoRoot(cwd);
309|	const ctx: LoadContext = { cwd, home, repoRoot };
310|	if (options.providers) ctx.explicitProviders = new Set(options.providers);
311|	if (options.includeDisabled) ctx.includeOptOutUserSources = true;
312|	if (options.extensionRoots !== undefined) ctx.extensionRoots = options.extensionRoots;
313|	const providers = filterProviders(capability, options);
314|
315|	return await loadImpl(capability, providers, ctx, options);
316|}
