318|// =============================================================================
319|// Provider Enable/Disable API
320|// =============================================================================
321|
322|/** Whether `providerId` is a foreign tool whose `~/` config is opt-in. */
323|export function isForeignUserProvider(providerId: string): boolean {
324|	return FOREIGN_USER_PROVIDERS[providerId] === true;
325|}
326|
327|/**
328| * Check whether a user-level (~/...) config source is enabled.
329| * Native (.tau) and .agents directories are enabled by default.
330| * Foreign tool directories (~/.cursor, ~/.codex, ~/.claude, etc.) are opt-in
331| * via `enabledProviders`. Project-level (cwd) config is unaffected; see
332| * {@link isProviderEnabled} for the whole-provider switch.
333| */
334|export function isUserSourceEnabled(source: string, ctx?: LoadContext): boolean {
335|	const id = source.replace(/^\./, "");
336|	if (disabledProviders.has(id)) return false;
337|	if (FOREIGN_USER_PROVIDERS[id] !== true) return true;
338|	if (ctx?.explicitProviders?.has(id) || ctx?.includeOptOutUserSources) return true;
339|	if (enabledProviders.has(id) || enabledProviders.has("*") || enabledProviders.has("all")) return true;
340|	if (id === "claude-plugins" && enabledProviders.has("claude")) return true;
341|	if (id === "claude" && process.env.CLAUDE_CONFIG_DIR?.trim()) return true;
342|	return false;
343|}
344|
345|/** Opt a foreign provider's `~/` config in. */
346|export function enableUserSource(providerId: string): void {
347|	enabledProviders.add(providerId);
348|	persistEnabledProviders();
349|}
350|
351|/** Opt a foreign provider's `~/` config out (project config keeps loading). */
352|export function disableUserSource(providerId: string): void {
353|	enabledProviders.delete(providerId);
354|	persistEnabledProviders();
355|}
356|
357|/**
358| * Initialize capability system with settings manager for persistence.
359| * Call this once on startup to enable persistent provider state.
360| */
361|export function initializeWithSettings(activeSettings: Settings): void {
362|	settings = activeSettings;
363|	// Load disabled providers from settings
364|	const disabled = settings.get("disabledProviders");
365|	disabledProviders.clear();
366|	for (const id of disabled) {
367|		disabledProviders.add(id);
368|	}
369|	// Load enabled providers from settings
370|	const enabled = settings.get("enabledProviders");
371|	enabledProviders.clear();
372|	for (const id of enabled) {
373|		enabledProviders.add(id);
374|	}
375|}
376|
377|/**
378| * Persist current disabled providers to settings.
379| */
380|function persistDisabledProviders(): void {
381|	if (settings) {
382|		settings.set("disabledProviders", Array.from(disabledProviders));
383|	}
384|}
385|
386|/**
387| * Persist current enabled providers to settings.
388| */
389|function persistEnabledProviders(): void {
390|	if (settings) {
391|		settings.set("enabledProviders", Array.from(enabledProviders));
392|	}
393|}
394|
395|/**
396| * Disable a provider globally (across all capabilities).
397| */
398|export function disableProvider(providerId: string): void {
399|	disabledProviders.add(providerId);
400|	persistDisabledProviders();
401|}
402|
403|/**
404| * Enable a previously disabled provider.
405| */
406|export function enableProvider(providerId: string): void {
407|	disabledProviders.delete(providerId);
408|	persistDisabledProviders();
409|}
410|
411|/**
412| * Check if a provider is enabled (the whole-provider switch backed by
413| * `disabledProviders`). Foreign `~/` config additionally needs
414| * {@link isUserSourceEnabled}.
415| */
416|export function isProviderEnabled(providerId: string): boolean {
417|	return !disabledProviders.has(providerId);
418|}
419|
420|/**
421| * Get list of all disabled provider IDs.
422| */
423|export function getDisabledProviders(): string[] {
424|	return Array.from(disabledProviders);
425|}
426|
427|/**
428| * Set disabled providers from a list (replaces current set).
429| */
430|export function setDisabledProviders(providerIds: string[]): void {
431|	disabledProviders.clear();
432|	for (const id of providerIds) {
433|		disabledProviders.add(id);
434|	}
435|	persistDisabledProviders();
436|}
437|
438|/**
439| * Get list of all explicitly enabled provider IDs.
440| */
441|export function getEnabledProviders(): string[] {
442|	return Array.from(enabledProviders);
443|}
444|
445|/**
446| * Set enabled providers from a list (replaces current set).
447| */
448|export function setEnabledProviders(providerIds: string[]): void {
449|	enabledProviders.clear();
450|	for (const id of providerIds) {
451|		enabledProviders.add(id);
452|	}
453|	persistEnabledProviders();
454|}
