456|// =============================================================================
457|// Introspection API
458|// =============================================================================
459|
460|/**
461| * Get a capability definition (for introspection).
462| */
463|export function getCapability<T>(id: string): Capability<T> | undefined {
464|	return capabilities.get(id) as Capability<T> | undefined;
465|}
466|
467|/**
468| * List all registered capability IDs.
469| */
470|export function listCapabilities(): string[] {
471|	return Array.from(capabilities.keys());
472|}
473|
474|/**
475| * Get capability info for UI display.
476| */
477|export function getCapabilityInfo(capabilityId: string): CapabilityInfo | undefined {
478|	const capability = capabilities.get(capabilityId);
479|	if (!capability) return undefined;
480|
481|	return {
482|		id: capability.id,
483|		displayName: capability.displayName,
484|		description: capability.description,
485|		providers: capability.providers.map(p => ({
486|			id: p.id,
487|			displayName: p.displayName,
488|			description: p.description,
489|			priority: p.priority,
490|			enabled: !disabledProviders.has(p.id),
491|		})),
492|	};
493|}
494|
495|/**
496| * Get all capabilities info for UI display.
497| */
498|export function getAllCapabilitiesInfo(): CapabilityInfo[] {
499|	return listCapabilities().map(id => getCapabilityInfo(id)!);
500|}
501|
502|/**
503| * Get provider info for UI display.
504| */
505|export function getProviderInfo(providerId: string): ProviderInfo | undefined {
506|	const meta = providerMeta.get(providerId);
507|	const caps = providerCapabilities.get(providerId);
508|	if (!meta || !caps) return undefined;
509|
510|	// Find priority from first capability's provider list
511|	let priority = 0;
512|	for (const capId of caps) {
513|		const cap = capabilities.get(capId);
514|		const provider = cap?.providers.find(p => p.id === providerId);
515|		if (provider) {
516|			priority = provider.priority;
517|			break;
518|		}
519|	}
520|
521|	return {
522|		id: providerId,
523|		displayName: meta.displayName,
524|		description: meta.description,
525|		priority,
526|		capabilities: Array.from(caps),
527|		enabled: !disabledProviders.has(providerId),
528|	};
529|}
530|
531|/**
532| * Get all providers info for UI display (deduplicated across capabilities).
533| */
534|export function getAllProvidersInfo(): ProviderInfo[] {
535|	const providers: ProviderInfo[] = [];
536|
537|	for (const providerId of providerMeta.keys()) {
538|		const info = getProviderInfo(providerId);
539|		if (info) {
540|			providers.push(info);
541|		}
542|	}
543|
544|	// Sort by priority (highest first)
545|	providers.sort((a, b) => b.priority - a.priority);
546|
547|	return providers;
548|}
