550|// =============================================================================
551|// Cache Management
552|// =============================================================================
553|
554|/**
555| * Reset all caches. Call after chdir or filesystem changes.
556| */
557|export function reset(): void {
558|	clearFsCache();
559|}
560|
561|/**
562| * Reset capability registry settings and provider state. Test-only.
563| */
564|export function resetCapabilityForTests(): void {
565|	settings = null;
566|	disabledProviders.clear();
567|	enabledProviders.clear();
568|	clearFsCache();
569|}
570|
571|/**
572| * Invalidate cache for a specific path.
573| * @param filePath - Absolute or relative path to invalidate
574| */
575|export function invalidate(filePath: string, cwd?: string): void {
576|	const resolved = cwd ? path.resolve(cwd, filePath) : filePath;
577|	invalidateFs(resolved);
578|}
579|
580|/**
581| * Get cache stats for diagnostics.
582| */
583|export function cacheStats(): { content: number; dir: number } {
584|	return fsCacheStats();
585|}
