#!/usr/bin/env bun
/**
 * Generate capability manifest from source analysis.
 * For MVP, we scan known export files and create a basic manifest.
 */
import { promises as fs } from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Capability types we know about
interface CapabilityEntry {
  name: string;
  kind: "export" | "hook" | "tool" | "provider" | "config";
  provider: string;
  aliases?: string[];
  synthesize?: string;
}

interface CapabilityManifest {
  schemaVersion: string;
  generatedAt: string;
  entries: CapabilityEntry[];
}

// Known capabilities that historically break plugins
const KNOWN_CAPABILITIES: CapabilityEntry[] = [
  {
    name: "@oh-my-pi/pi-coding-agent#keyText",
    kind: "export",
    provider: "src/extensibility/shim.ts",
    aliases: ["@mariozechner/pi-coding-agent#keyText"],
    synthesize: `export function keyText(action) {
  return formatKeyHints(getKeybindings().getKeys(action));
}`,
  },
  {
    name: "@oh-my-pi/pi-agent-core#compact",
    kind: "export",
    provider: "src/agent-plugin-format.ts",
    aliases: ["@mariozechner/pi-agent-core#compact"],
  },
  {
    name: "@oh-my-pi/pi-coding-agent#ctx.ui.confirm",
    kind: "hook",
    provider: "src/hook.ts",
    aliases: ["@mariozechner/pi-coding-agent#ctx.ui.confirm"],
  },
  {
    name: "@oh-my-pi/pi-agent-core#withFileMutationQueue",
    kind: "hook",
    provider: "src/agent-plugin-format.ts",
    aliases: ["@mariozechner/pi-agent-core#withFileMutationQueue"],
  },
];

async function main() {
  const manifest: CapabilityManifest = {
    schemaVersion: "1.0.0",
    generatedAt: new Date().toISOString(),
    entries: KNOWN_CAPABILITIES,
  };

  const outDir = path.resolve(__dirname, "..", "dist");
  await fs.mkdir(outDir, { recursive: true });
  const outFile = path.join(outDir, "manifest.json");
  await fs.writeFile(outFile, JSON.stringify(manifest, null, 2));
  console.log(`Generated capability manifest at ${outFile}`);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

