334|function lineRangePath(readPath: string, offset: number | undefined, limit: number | undefined): string {
335|	if (offset === undefined && limit === undefined) return readPath;
336|	const start = Math.max(1, Math.floor(offset ?? 1));
337|	if (limit === undefined) return `${readPath}:${start}`;
338|	const end = Math.max(start, start + Math.max(1, Math.floor(limit)) - 1);
339|	return `${readPath}:${start}-${end}`;
340|}
