351|function legacyBashSnapshot(output: string): { text: string; details?: { truncation: TruncationResult } } {
352|	const truncation = truncateTail(output, { maxLines: DEFAULT_MAX_LINES, maxBytes: DEFAULT_MAX_BYTES });
353|	if (!truncation.truncated) {
354|		return { text: truncation.content };
355|	}
356|	const startLine = truncation.totalLines - (truncation.outputLines ?? 0) + 1;
357|	const note =
358|		truncation.truncatedBy === "lines"
359|			? `Showing lines ${startLine}-${truncation.totalLines} of ${truncation.totalLines}`
360|			: `Showing lines ${startLine}-${truncation.totalLines} of ${truncation.totalLines} (${formatBytes(DEFAULT_MAX_BYTES)} limit)`;
361|	return {
362|		text: `${truncation.content}\n\n[${note}]`,
363|		details: { truncation },
364|	};
