367|async function executeLegacyBashOperations(
368|	operations: BashOperations,
369|	spawn: BashSpawnContext,
370|	timeout: number | undefined,
371|	signal: AbortSignal | undefined,
372|	onUpdate: AgentToolUpdateCallback | undefined,
373|): Promise<AgentToolResult> {
374|	let output = "";
375|	const onData = (data: Buffer) => {
376|		output += data.toString("utf8");
377|		if (onUpdate) {
378|			const snapshot = legacyBashSnapshot(output);
379|			onUpdate({ content: [{ type: "text", text: snapshot.text }], details: snapshot.details });
380|		}
381|	};
382|	try {
383|		const result = await operations.exec(spawn.command, spawn.cwd, {
384|			onData,
385|			signal,
386|			timeout,
387|			env: spawn.env,
388|		});
389|		const snapshot = legacyBashSnapshot(output);
390|		const text = snapshot.text || "(no output)";
391|		if (result.exitCode !== 0 && result.exitCode !== null) {
392|			throw new Error(appendStatus(text, `Command exited with code ${result.exitCode}`));
393|		}
394|		return { content: [{ type: "text", text }], details: snapshot.details };
395|	} catch (err) {
396|		const snapshot = legacyBashSnapshot(output);
397|		const text = snapshot.text;
398|		if (err instanceof Error && err.message === "aborted") {
399|			throw new Error(appendStatus(text, "Command aborted"));
400|		}
401|		if (err instanceof Error && err.message.startsWith("timeout:")) {
402|			throw new Error(appendStatus(text, `Command timed out after ${err.message.slice("timeout:".length)} seconds`));
403|		}
404|		throw err;
405|	}
