1357|export async function createAgentSession(
1358|	options: LegacyPiCreateAgentSessionOptions = {},
1359|): Promise<CreateAgentSessionResult> {
1360|	const loader = options.resourceLoader;
1361|	if (!loader) {
1362|		return ompCreateAgentSession(options);
1363|	}
1364|
1365|	if (loader instanceof DefaultResourceLoader && !loader.loaded) {
1366|		await loader.reload();
1367|	}
1368|
1369|	const state =
1370|		loader instanceof DefaultResourceLoader
1371|			? loader.__getResolverState()
1372|			: {
1373|					cwd: options.cwd ?? getProjectDir(),
1374|					agentDir: options.agentDir ?? getAgentDir(),
1375|					settingsPromise: undefined,
1376|					eventBus: undefined,
1377|					extensionsResult: loader.getExtensions(),
1378|					skills: loader.getSkills().skills,
1379|					prompts: loader.getPrompts().prompts,
1380|					agentsFiles: loader.getAgentsFiles().agentsFiles,
1381|					systemPrompt: loader.getSystemPrompt(),
1382|					appendSystemPrompt: loader.getAppendSystemPrompt(),
1383|					extensionFactories: [] as ExtensionFactory[],
1384|				};
1385|
1386|	const { resourceLoader: _, ...rest } = options;
1387|	const forwarded: CreateAgentSessionOptions = {
1388|		...rest,
1389|		cwd: rest.cwd ?? state.cwd,
1390|		agentDir: rest.agentDir ?? state.agentDir,
1391|	};
1392|
1393|	if (rest.eventBus === undefined && state.eventBus !== undefined) {
1394|		forwarded.eventBus = state.eventBus;
1395|	}
1396|	if (rest.settings === undefined && rest.settingsManager === undefined && state.settingsPromise !== undefined) {
1397|		forwarded.settingsManager = state.settingsPromise;
1398|	}
