1400|	// Route the loader's already-loaded extension result through the SDK's
1401|	// `preloadedExtensions` seam. Skipping this branch would let
1402|	// `createAgentSession` re-run its own discovery and undo the caller's
1403|	// `noExtensions: true`.
1404|	if (
1405|		rest.preloadedExtensions === undefined &&
1406|		rest.preloadedPreparedExtensions === undefined &&
1407|		rest.preloadedExtensionPaths === undefined
1408|	) {
1409|		forwarded.preloadedExtensions = state.extensionsResult;
1410|	}
1411|
1412|	if (rest.skills === undefined) {
1413|		forwarded.skills = state.skills;
1414|	}
1415|	if (rest.promptTemplates === undefined) {
1416|		forwarded.promptTemplates = state.prompts;
1417|	}
1418|	if (rest.contextFiles === undefined) {
1419|		forwarded.contextFiles = state.agentsFiles;
1420|	}
1421|
1422|	if (rest.systemPrompt === undefined && state.systemPrompt !== undefined) {
1423|		forwarded.systemPrompt = state.systemPrompt;
1424|	}
