214|/**
215| * Chain a single-model subagent inherits when its own model patterns supply no
216| * fallbacks of their own. The child is pinned to a `subagent:<id>` role whose
217| * chain shadows every configured role chain (see
218| * {@link installSubagentRetryFallbackChain}), so a role-alias request (`@smol`,
219| * the bundled `task` agent's `@task`) MUST inherit that role's chain —
220| * otherwise the pin silently re-routes the child onto the `default` role's
221| * chain. Explicit model selectors keep inheriting `default`: they carry no role
222| * identity, and a role that happens to be assigned the same model must not
223| * capture the child's fallback routing.
224| *
225| * Spawn paths preserve the pre-expansion alias as `modelRole` because their
226| * model patterns are already expanded. Direct callers may still supply an
227| * unexpanded alias through `modelOverride` or `agent.model`; retain that
228| * existing path by deriving the role only when no preserved role was supplied.
229| */
230|function resolveSubagentInheritedRetryFallbackChain(
231|	settings: Settings,
232|	modelRegistry: ModelRegistry,
233|	role: string | undefined,
234|): string[] | undefined {
235|	const configuredChains = settings.get("retry.fallbackChains");
236|	// An explicitly emptied role chain means "no fallbacks", not "inherit
237|	// default" — mirrors expandDefaultRetryFallbackChains.
238|	const fallbackChain = (role !== undefined ? configuredChains?.[role] : undefined) ?? configuredChains?.default;
239|	if (
240|		!Array.isArray(fallbackChain) ||
241|		fallbackChain.length === 0 ||
242|		!fallbackChain.every(entry => typeof entry === "string")
243|	) {
244|		return undefined;
245|	}
246|	const disabledProviders = new Set(settings.get("disabledProviders"));
247|	return fallbackChain.filter(entry => {
248|		const resolved = resolveModelOverride([entry], modelRegistry, settings);
249|		return !resolved.model || !disabledProviders.has(resolved.model.provider);
250|	});
251|}
