2629|		const from = details ? Reflect.get(details, "from") : undefined;
2630|		if (typeof from !== "string" || from === selfId || sources.some(source => source.from === from)) continue;
2631|		// Automated wake-turn relays are answers, not wake sources: relaying one
2632|		// back would ping-pong two idle peers forever.
2633|		if (details && Reflect.get(details, "wakeRelay") === true) continue;
2634|		const messageId = details ? Reflect.get(details, "id") : undefined;
