2706|export function buildWakeRelayBody(args: {
2707|	id: string;
2708|	yielded: boolean;
2709|	result: SingleResult | undefined;
2710|	turnText: string;
2711|	error: string | undefined;
2712|	aborted: boolean;
2713|	abortReason: string | undefined;
2714|	finalizeError: unknown;
2715|	alreadyMessaged: boolean;
