2726|		? `Wake turn failed: ${args.error}.`
2727|		: args.aborted
2728|			? `Wake turn was cancelled${args.abortReason?.trim() ? `: ${args.abortReason.trim()}` : ""}.`
2729|			: undefined;
2730|	if (headline) {
2731|		if (summary) {
2732|			return `${headline} A result was recorded before the turn ended:\n\n${summary}\n\n${transcript}`;
2733|		}
2734|		const context = args.alreadyMessaged
2735|			? "You received a message earlier in this turn, but that was not the answer and nothing further was sent."
2736|			: "No answer was produced.";
2737|		return `${headline} ${context} ${transcript}`;
2738|	}
2739|
2740|	// Completed lane. `alreadyMessaged` completed turns were filtered upstream
2741|	// (their answer would duplicate what the agent already sent).
2742|	const answer = summary ?? args.turnText.trim();
2743|	if (answer) return answer;
2744|	if (args.finalizeError) {
2745|		const message = args.finalizeError instanceof Error ? args.finalizeError.message : String(args.finalizeError);
