192|function resolveSubagentRetryFallbackCandidates(
193|	modelPatterns: string[],
194|	modelRegistry: ModelRegistry,
195|	settings: Settings,
196|): SubagentRetryFallbackCandidate[] {
197|	const candidates: SubagentRetryFallbackCandidate[] = [];
198|	const seen = new Set<string>();
199|	const disabledProviders = new Set(settings.get("disabledProviders"));
200|	for (const pattern of modelPatterns) {
201|		const resolved = resolveModelOverride([pattern], modelRegistry, settings);
202|		if (!resolved.model) continue;
203|		if (disabledProviders.has(resolved.model.provider)) continue;
204|		const selector = resolved.explicitThinkingLevel
205|			? formatModelSelectorValue(formatModelStringWithRouting(resolved.model), resolved.thinkingLevel)
206|			: formatModelStringWithRouting(resolved.model);
207|		if (seen.has(selector)) continue;
208|		seen.add(selector);
209|		candidates.push({ model: resolved.model, selector });
210|	}
211|	return candidates;
