2624|function wakeSources(records: AgentMessage[], selfId: string): WakeSource[] {
2625|	const sources: WakeSource[] = [];
2626|	for (const record of records) {
2627|		if (record.role !== "custom") continue;
2628|		const details = record.details && typeof record.details === "object" ? record.details : undefined;
2629|		const from = details ? Reflect.get(details, "from") : undefined;
2630|		if (typeof from !== "string" || from === selfId || sources.some(source => source.from === from)) continue;
