2632|		// back would ping-pong two idle peers forever.
2633|		if (details && Reflect.get(details, "wakeRelay") === true) continue;
2634|		const messageId = details ? Reflect.get(details, "id") : undefined;
2635|		sources.push({ from, messageId: typeof messageId === "string" ? messageId : undefined });
