2649|async function relayWakeTurnOutput(args: {
2650|	id: string;
2651|	records: AgentMessage[];
2652|	turnStartTime: number;
2653|	yielded: boolean;
2654|	result: SingleResult | undefined;
2655|	turnText: string;
2656|	/** Short, attributed peer-visible error text (no stack) when the turn died on an error. */
2657|	error: string | undefined;
2658|	/** Whether the turn was aborted (runtime limit, cancellation, hard abort). */
2659|	aborted: boolean;
2660|	/** Reason text for an aborted turn, from {@link SubagentRunMonitor.resolveAbortReasonText}. */
2661|	abortReason: string | undefined;
2662|	/** A {@link finalizeRunResult} throw, so the waiter is notified instead of stranded. */
2663|	finalizeError: unknown;
2664|}): Promise<void> {
2665|	const bus = IrcBus.global();
2666|	const sources = wakeSources(args.records, args.id);
2667|	if (sources.length === 0) return;
2668|	const failed = args.error !== undefined || args.aborted || args.finalizeError !== undefined;
2669|	for (const source of sources) {
2670|		const alreadyMessaged = bus.sentSince(args.id, source.from, args.turnStartTime);
2671|		// A completed turn's answer would duplicate what the agent already sent
2672|		// this waker, so dedup stays. A failed/cancelled turn is a distinct
2673|		// lifecycle fact: `sentSince` cannot tell "already answered you" from
2674|		// "pinged you 'on it'", and suppressing the failure notice on a mere ping
2675|		// strands the waker exactly as before — one message later. So the failure
2676|		// lane always notifies, flavoured to acknowledge the earlier message.
2677|		if (alreadyMessaged && !failed) continue;
2678|		const body = buildWakeRelayBody({ ...args, alreadyMessaged });
2679|		if (!body) continue;
2680|		const receipt = await bus.send({
2681|			from: args.id,
2682|			to: source.from,
2683|			body,
2684|			replyTo: source.messageId,
2685|			wakeRelay: true,
2686|		});
2687|		if (receipt.outcome === "failed") {
2688|			logger.warn("IRC wake-turn relay failed", { from: args.id, to: source.from, error: receipt.error });
