146|/** Steering notice injected when a subagent crosses its soft request budget. */
147|export function buildBudgetNotice(requests: number, budget: number): string {
148|	return `[budget notice] You have used ${requests} requests in this run (soft budget: ${budget}). Wrap up now: finish the current step and yield your final report. At ${Math.ceil(budget * 1.5)} requests the run is force-stopped and you will be asked to yield whatever you have.`;
