192|function resolveSubagentRetryFallbackCandidates(
193|	modelPatterns: string[],
194|	modelRegistry: ModelRegistry,
195|	settings: Settings,
196|): SubagentRetryFallbackCandidate[] {
197|	const candidates: SubagentRetryFallbackCandidate[] = [];
198|	const seen = new Set<string>();
199|	const disabledProviders = new Set(settings.get("disabledProviders"));
200|	for (const pattern of modelPatterns) {
