321|export function collectIrcPeerRoster(
322|	registry: AgentRegistry,
323|	selfId: string,
324|	rootSessionFile?: string,
325|): IrcPeerRosterData {
326|	// Same ordering as `hub list`: running before idle, then newest activity
327|	// first — so the cap keeps the newest relevant siblings, not an
328|	// insertion-order prefix.
329|	const live = registry
330|		.listVisibleTo(selfId)
331|		.sort(
332|			(a, b) =>
333|				(LIST_STATUS_ORDER[a.status] ?? 9) - (LIST_STATUS_ORDER[b.status] ?? 9) || b.lastActivity - a.lastActivity,
334|		);
335|	const limit = DEFAULT_HUB_LIST_LIMIT;
336|	const omittedCount = Math.max(0, live.length - limit);
337|	const peers = (omittedCount > 0 ? live.slice(0, limit) : live).map(peer => ({
338|		id: peer.id,
339|		displayName: peer.displayName,
340|		kind: peer.kind,
341|		status: peer.status,
342|		activity: peer.activity,
343|	}));
344|	let parkedCount = 0;
345|	for (const ref of registry.list()) {
346|		if (
347|			ref.id !== selfId &&
348|			ref.kind !== "advisor" &&
349|			ref.status === "parked" &&
350|			isCurrentSessionRosterRef(ref, rootSessionFile)
351|		) {
352|			parkedCount++;
353|		}
354|	}
355|	return { peers, parkedCount, omittedCount };
