113|/**
114| * Soft per-agent request budgets (assistant requests per run). Crossing the
115| * budget injects a wrap-up steering notice (`task.softRequestBudgetNotice`,
116| * on by default). At 1.5x the budget the free-running turn is stopped and the
117| * agent is driven to one forced final `yield` so partial findings come back
118| * as a real report; only if it still refuses to yield within
119| * {@link BUDGET_STOP_GRACE_REQUESTS} more requests is the run hard-aborted.
120| * Entries are ceilings, not fixed values: the `default` key applies to agents
121| * without an explicit entry, and the `task.softRequestBudget` setting can only
122| * lower an agent's budget, never raise it above its bundled entry (0 disables
123| * the guard entirely).
124| */
125|export const SOFT_REQUEST_BUDGET: Record<string, number> = {
126|	scout: 100,
127|	sonic: 100,
128|	default: 200,
129|};
130|
131|/**
132| * Resolves the effective soft request budget for an agent. The configured
133| * `task.softRequestBudget` and the agent's bundled entry are both upper
134| * bounds, so the tighter one wins; a configured budget of 0 disables the
135| * guard regardless of the bundled entry.
136| */
137|export function resolveSoftRequestBudget(agentName: string, configuredBudget: number): number {
138|	const normalized = Math.max(0, Math.trunc(configuredBudget));
139|	if (normalized === 0) return 0;
140|	return Math.min(normalized, SOFT_REQUEST_BUDGET[agentName] ?? normalized);
141|}
