2672|		// this waker, so dedup stays. A failed/cancelled turn is a distinct
2673|		// lifecycle fact: `sentSince` cannot tell "already answered you" from
2674|		// "pinged you 'on it'", and suppressing the failure notice on a mere ping
2675|		// strands the waker exactly as before — one message later. So the failure
2676|		// lane always notifies, flavoured to acknowledge the earlier message.
2677|		if (alreadyMessaged && !failed) continue;
2678|		const body = buildWakeRelayBody({ ...args, alreadyMessaged });
