358|function withAbortTimeout<T>(
359|	promise: Promise<T>,
360|	timeoutMs: number,
361|	signal?: AbortSignal,
362|	timeoutController?: AbortController,
363|): Promise<T> {
364|	if (signal?.aborted) {
365|		return Promise.reject(new ToolAbortError());
366|	}
367|
368|	const { promise: wrappedPromise, resolve, reject } = Promise.withResolvers<T>();
369|	let settled = false;
370|	const timeoutId = setTimeout(() => {
371|		if (settled) return;
372|		settled = true;
373|		timeoutController?.abort(new DOMException(`MCP tool call timed out after ${timeoutMs}ms`, "TimeoutError"));
374|		reject(new Error(`MCP tool call timed out after ${timeoutMs}ms`));
375|	}, timeoutMs);
376|
377|	const onAbort = () => {
378|		if (settled) return;
379|		settled = true;
380|		clearTimeout(timeoutId);
381|		timeoutController?.abort();
382|		reject(new ToolAbortError());
383|	};
384|
385|	if (signal) {
386|		signal.addEventListener("abort", onAbort, { once: true });
387|	}
388|
389|	promise.then(resolve, reject).finally(() => {
390|		if (signal) signal.removeEventListener("abort", onAbort);
391|		clearTimeout(timeoutId);
392|	});
393|
394|	return wrappedPromise;
395|}
