253|function installSubagentRetryFallbackChain(args: {
254|	settings: Settings;
255|	id: string;
256|	candidates: SubagentRetryFallbackCandidate[];
257|	inheritedFallbackChain: string[] | undefined;
258|	model: Model<Api> | undefined;
259|	authFallbackUsed: boolean;
260|}): string | undefined {
261|	const { settings, id, candidates, inheritedFallbackChain, model, authFallbackUsed } = args;
262|	if (!model || authFallbackUsed || candidates.length === 0) return undefined;
263|
264|	const selectedIndex = candidates.findIndex(
265|		candidate => candidate.model.provider === model.provider && candidate.model.id === model.id,
266|	);
267|	if (selectedIndex < 0) return undefined;
268|	const fallbackSelectors = candidates.slice(selectedIndex + 1).map(candidate => candidate.selector);
269|	const existingFallbackChains = settings.get("retry.fallbackChains");
270|	// A single configured model may reuse its role's (or the default) configured chain, but never an implicit parent fallback.
271|	const fallbackChain = fallbackSelectors.length > 0 ? fallbackSelectors : inheritedFallbackChain;
272|	if (
273|		!Array.isArray(fallbackChain) ||
274|		fallbackChain.length === 0 ||
275|		!fallbackChain.every(entry => typeof entry === "string")
276|	) {
277|		return undefined;
278|	}
279|
280|	const role = `${SUBAGENT_RETRY_FALLBACK_ROLE_PREFIX}${id}`;
281|	const modelRoles: Record<string, string> = {};
282|	const existingRoles = settings.getModelRoles();
283|	for (const existingRole in existingRoles) {
284|		const selector = existingRoles[existingRole];
285|		if (selector) {
286|			modelRoles[existingRole] = selector;
287|		}
288|	}
289|	modelRoles[role] = candidates[selectedIndex].selector;
290|	settings.override("modelRoles", modelRoles);
291|	// Insert the task-specific role first so another role assigned to the same model cannot capture fallback routing.
292|	const fallbackChains: Record<string, string[]> = {
293|		[role]: fallbackChain,
294|	};
295|	for (const existingRole in existingFallbackChains) {
296|		if (existingRole !== role) {
297|			fallbackChains[existingRole] = existingFallbackChains[existingRole];
298|		}
299|	}
300|	settings.override("retry.fallbackChains", fallbackChains);
301|	return role;
302|}
