#!/usr/bin/env bun
/**
 * Background reader that proposes synthesis hints for missing capabilities.
 * Reads failure records, uses LLM to propose a hint, validates, and updates registry.
 */

import { promises as fs } from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repairDir = path.join(os.homedir(), ".omp", "repair");
const capabilitiesDir = path.join(__dirname, "..");
const registryPath = path.join(capabilitiesDir, "registry.toml");
const manifestPath = path.join(capabilitiesDir, "dist", "manifest.json");

interface FailureRecord {
  capability: string;
  timestamp: string;
  [key: string]: unknown;
}

/**
 * Placeholder LLM call: returns a hint based on capability name.
 * In reality, this would call an LLM with context.
 */
async function proposeHintWithLLM(capabilityName: string): Promise<string> {
  // Simulate LLM response: generate a simple shim template
  // This is just a placeholder; real implementation would call an LLM.
  return `// Placeholder hint for ${capabilityName}
export function placeholder() {
  return "TODO: implement hint for ${capabilityName}";
}`;
}

/**
 * Validate a hint string: must be non-empty.
 */
function validateHint(hint: string): boolean {
  return hint && hint.length > 0;
}

/**
 * Update registry.toml to add or update the synthesize hint for a capability.
 */
async function updateRegistryWithHint(
  capabilityName: string,
  hint: string,
): Promise<void> {
  let content = await fs.readFile(registryPath, "utf-8");
  // Simple approach: replace or add a synthesize line under the capability entry.
  // For simplicity, we'll just append a comment and a line at the end.
  // In a real implementation, we would parse TOML properly.
  const update = `
# Hint for ${capabilityName} (added by background reader)
${capabilityName}.synthesize = """${hint.replace(/"/g, '\\"')}""`;
  content += update;
  await fs.writeFile(registryPath, content);
}

/**
 * Main loop: process all failure records.
 */
async function main() {
  try {
    await fs.access(repairDir);
  } catch {
    console.log("No repair directory found.");
    return;
  }

  const files = await fs.readdir(repairDir);
  const failureFiles = files.filter(f => f.startsWith("missing-") && f.endsWith(".json"));

  if (failureFiles.length === 0) {
    console.log("No failure records to process.");
    return;
  }

  console.log(`Processing ${failureFiles.length} failure records...`);

  for (const file of failureFiles) {
    const filePath = path.join(repairDir, file);
    const raw = await fs.readFile(filePath, "utf-8");
    let record: FailureRecord;
    try {
      record = JSON.parse(raw);
    } catch (e) {
      console.warn(`Failed to parse ${file}: ${e}`);
      continue;
    }

    const capabilityName = record.capability;
    console.log(`Processing capability: ${capabilityName}`);

    // Check if we already have a hint in manifest (optional)
    // For simplicity, we always attempt to propose.

    const hint = await proposeHintWithLLM(capabilityName);
    if (!validateHint(hint)) {
      console.warn(`Invalid hint for ${capabilityName}`);
      continue;
    }

    try {
      await updateRegistryWithHint(capabilityName, hint);
      console.log(`Updated registry with hint for ${capabilityName}`);

      // Optionally, remove the failure record after success
      await fs.unlink(filePath);
      console.log(`Removed failure record ${file}`);
    } catch (e) {
      console.error(`Failed to update registry for ${capabilityName}: ${e}`);
    }
  }

  // After updating registry, regenerate manifest
  const { genManifest } = await import("./gen-manifest");
  await genManifest();
  console.log("Regenerated manifest.");
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

