#!/usr/bin/env bun
/**
 * Migration tool for existing plugins to declare requirements.
 * Scans a plugin directory and suggests a requires block.
 */
import { promises as fs } from "node:fs";
import * as path from "node:path";

const pluginDir = process.argv[2];
if (!pluginDir) {
  console.error("Usage: bun run migrate.js <plugin-dir>");
  process.exit(1);
}

async function main() {
  const manifestPath = path.join(pluginDir, "package.json");
  let pkg;
  try {
    const raw = await fs.readFile(manifestPath, "utf-8");
    pkg = JSON.parse(raw);
  } catch (e) {
    console.error(`Failed to read ${manifestPath}: ${e}`);
    process.exit(1);
  }

  // Placeholder detection: assume plugin uses keyText and compact
  const suggestedRequires = [
    "@oh-my-pi/pi-coding-agent#keyText",
    "@oh-my-pi/pi-agent-core#compact",
  ];

  pkg.toxicwind = {
    requires: suggestedRequires,
    policy: {
      tools: {
        bash: { kind: "escalate", to: "parent" }
      }
    }
  };

  await fs.writeFile(manifestPath, JSON.stringify(pkg, null, 2));
  console.log(`Updated ${manifestPath} with toxicwind.requires`);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

